def main() -> None:
    current_lod_switch = None

    for scene_idx, scene in enumerate(SCENES):
        print(f"\n{'='*60}")
        print(f"Scene {scene_idx + 1}/{len(SCENES)}: {scene['input_xml']}")
        print(f"{'='*60}")

        current_lod_switch = run_scene(
            input_xml=scene["input_xml"],
            output_xml=scene["output_xml"],
            executable=EXECUTABLE,
            executable_src_file=EXECUTABLE_SRC,
            runs=scene["runs"],
            current_lod_switch=current_lod_switch,
        )

    print("\nAll scenes complete.")


if __name__ == "__main__":
    main()